[GQL-EXEC cleanup_pre]
[GQL-OP find_lt001]
  query($storeId: String!, $userId: String!, $filter: String!) {
    products(storeId: $storeId userId: $userId currencyCode: "USD" cultureName: "en-US" filter: $filter first: 1) {
      items { id code }
    }
  }
[GQL-VARS find_lt001] {"storeId": "{{STORE_ID}}", "userId": "{{USER_ID}}", "filter": "code:LT-001 category.subtree:@td(VIRTUAL_CATALOG_B2B.id)"}
[GQL-EXEC find_lt001]
[GQL-CAPTURE find_lt001.data.products.items.0.id → LT001_ID]
[GQL-OP add_lt001]
  mutation { addItem(command: { cartName: "default" storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" productId: "{{LT001_ID}}" quantity: 1 }) { id } }
[GQL-EXEC add_lt001]
[GQL-OP read_cart_preview]
  query {
    cart(cartName: "default" storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" currencyCode: "USD" cultureName: "en-US") {
      id
      items { sku loyaltyPoints { amount currency { code } } }
      loyaltyPoints { amount currency { code } }
      availableShippingMethods { code optionName price { amount } }
      availablePaymentMethods { code }
    }
  }
[GQL-EXEC read_cart_preview]
[GQL-CAPTURE read_cart_preview.data.cart.id → CART_ID]
[GQL-CAPTURE read_cart_preview.data.cart.items[?sku=LT-001].loyaltyPoints.amount → PREVIEW_ITEM_PTS]
[GQL-CAPTURE read_cart_preview.data.cart.loyaltyPoints.amount → PREVIEW_CART_PTS]
[GQL-CAPTURE read_cart_preview.data.cart.availableShippingMethods[?code=FixedRate].code → SHIP_CODE]
[GQL-CAPTURE read_cart_preview.data.cart.availableShippingMethods[?code=FixedRate].optionName → SHIP_OPTION]
[GQL-CAPTURE read_cart_preview.data.cart.availableShippingMethods[?code=FixedRate].price.amount → SHIP_PRICE]
[GQL-OP set_shipment]
  mutation { addOrUpdateCartShipment(command: { storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" currencyCode: "USD" cultureName: "en-US" shipment: { shipmentMethodCode: "{{SHIP_CODE}}" shipmentMethodOption: "{{SHIP_OPTION}}" price: {{SHIP_PRICE}} deliveryAddress: { firstName: "Test" lastName: "Agent" line1: "100 Main St" city: "New York" countryCode: "US" countryName: "United States" postalCode: "10001" regionId: "US-NY" regionName: "New York" } } }) { id } }
[GQL-EXEC set_shipment]
[GQL-OP set_payment]
  mutation { addOrUpdateCartPayment(command: { storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" currencyCode: "USD" cultureName: "en-US" payment: { paymentGatewayCode: "DefaultManualPaymentMethod" } }) { id } }
[GQL-EXEC set_payment]
[GQL-OP place_order]
  mutation { createOrderFromCart(command: { cartId: "{{CART_ID}}" }) { id number } }
[GQL-EXEC place_order]
[GQL-CAPTURE place_order.data.createOrderFromCart.number → ORDER_NUMBER]
[GQL-CAPTURE place_order.data.createOrderFromCart.id → ORDER_ID]
[GQL-OP balance_after]
  query { loyaltyBalance(userId: "{{USER_ID}}") { currentBalance resultBalance } }
[GQL-EXEC balance_after]
[WAIT until=balance_after timeout=40 interval=4] data.loyaltyBalance.currentBalance > {{BAL_BEFORE}}
[GQL-CAPTURE balance_after.data.loyaltyBalance.currentBalance → BAL_AFTER]
[GQL-OP history_check]
  query { loyaltyPointsHistory(userId: "{{USER_ID}}" first: 5 sort: "createdDate:desc") { totalCount items { operationType amount createdDate object { orderId type } } } }
[GQL-EXEC history_check]
[GQL-OP cleanup_post]
  mutation { clearCart(command: { storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" cartName: "default" }) { id } }
[GQL-EXEC cleanup_post]

Cleanup:
